mapper.update:
UPDATE NAS_FILE
   SET DELETE_YN = 'Y',
       DELETED_AT = NOW(),
       TRASH_ID = #{trashId}
 WHERE USER_CODE = #{userCode}
   AND FOLDER_ID = #{folderId}
   AND FILE_ID = #{fileId}
   AND DELETE_YN = 'N'

mapper.select:
SELECT T.TRASH_ID, COALESCE(F.FILE_ID, D.FOLDER_ID) AS ITEM_ID, COALESCE(F.ORIGIN_NAME, D.FOLDER_NAME) AS ITEM_NAME, T.ROOT_ITEM_TYPE AS ITEM_TYPE, COALESCE(F.FILE_SIZE, 0) AS ITEM_SIZE, F.EXTENSION, T.ORIGINAL_PARENT_ID, TO_CHAR(T.DELETED_AT, 'YYYY-MM-DD HH24:MI:SS') AS DELETED_AT, TO_CHAR(T.EXPIRES_AT, 'YYYY-MM-DD HH24:MI:SS') AS EXPIRES_AT, GREATEST( 0, CEIL(EXTRACT(EPOCH FROM (T.EXPIRES_AT - NOW())) / 86400)::INTEGER ) AS REMAINING_DAYS, T.PURGE_STATUS FROM NAS_TRASH_ENTRY T LEFT JOIN NAS_FILE F ON T.ROOT_ITEM_TYPE = 'FILE' AND F.FILE_ID = T.ROOT_ITEM_ID AND F.TRASH_ID = T.TRASH_ID LEFT JOIN NAS_FOLDER D ON T.ROOT_ITEM_TYPE = 'FOLDER' AND D.FOLDER_ID = T.ROOT_ITEM_ID AND D.TRASH_ID = T.TRASH_ID WHERE T.USER_CODE = #{userCode} AND T.PURGE_STATUS = 'ACTIVE'
AND COALESCE(F.ORIGIN_NAME, D.FOLDER_NAME, '') ILIKE '%' || #{keyword} || '%'
ORDER BY T.DELETED_AT DESC, T.TRASH_ID LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM NAS_TRASH_ENTRY
 WHERE USER_CODE = #{userCode}
   AND PURGE_STATUS = 'ACTIVE'
   AND TRASH_ID IN

    #{trashId}

mapper.update:
UPDATE NAS_FILE F SET FOLDER_ID = ( SELECT R.FOLDER_ID FROM NAS_FOLDER R WHERE R.USER_CODE = #{userCode} AND R.FOLDER_ID = R.PARENT_FOLDER_ID AND R.DELETE_YN = 'N' LIMIT 1 ) FROM NAS_TRASH_ENTRY T WHERE T.USER_CODE = #{userCode} AND T.PURGE_STATUS = 'ACTIVE' AND T.ROOT_ITEM_TYPE = 'FILE' AND T.TRASH_ID IN
#{trashId}
AND F.FILE_ID = T.ROOT_ITEM_ID AND F.TRASH_ID = T.TRASH_ID AND NOT EXISTS ( SELECT 1 FROM NAS_FOLDER P WHERE P.USER_CODE = #{userCode} AND P.FOLDER_ID = F.FOLDER_ID AND P.DELETE_YN = 'N' ) AND NOT EXISTS ( SELECT 1 FROM NAS_FOLDER P WHERE P.USER_CODE = #{userCode} AND P.FOLDER_ID = F.FOLDER_ID AND P.TRASH_ID IN
#{trashId}
)

UPDATE NAS_FOLDER F SET PARENT_FOLDER_ID = ( SELECT R.FOLDER_ID FROM NAS_FOLDER R WHERE R.USER_CODE = #{userCode} AND R.FOLDER_ID = R.PARENT_FOLDER_ID AND R.DELETE_YN = 'N' LIMIT 1 ) FROM NAS_TRASH_ENTRY T WHERE T.USER_CODE = #{userCode} AND T.PURGE_STATUS = 'ACTIVE' AND T.ROOT_ITEM_TYPE = 'FOLDER' AND T.TRASH_ID IN
#{trashId}
AND F.FOLDER_ID = T.ROOT_ITEM_ID AND F.TRASH_ID = T.TRASH_ID AND NOT EXISTS ( SELECT 1 FROM NAS_FOLDER P WHERE P.USER_CODE = #{userCode} AND P.FOLDER_ID = F.PARENT_FOLDER_ID AND P.DELETE_YN = 'N' ) AND NOT EXISTS ( SELECT 1 FROM NAS_FOLDER P WHERE P.USER_CODE = #{userCode} AND P.FOLDER_ID = F.PARENT_FOLDER_ID AND P.TRASH_ID IN
#{trashId}
)

UPDATE NAS_FILE_PREVIEW P SET DELETE_YN = 'N', DELETED_AT = NULL WHERE P.DELETE_YN = 'Y' AND P.FILE_ID IN ( SELECT F.FILE_ID FROM NAS_FILE F WHERE F.USER_CODE = #{userCode} AND F.DELETE_YN = 'Y' AND F.TRASH_ID IN
#{trashId}
)

mapper.select:
SELECT F.FILE_ID, F.STORAGE_PATH, F.STORED_NAME, P.STORAGE_PATH AS PREVIEW_STORAGE_PATH, P.STORED_NAME AS PREVIEW_STORED_NAME FROM NAS_FILE F LEFT JOIN NAS_FILE_PREVIEW P ON P.FILE_ID = F.FILE_ID WHERE F.DELETE_YN = 'Y' AND F.TRASH_ID IN
#{trashId}
AND F.USER_CODE = #{userCode}

