DELETE FROM NAS_FOLDER F WHERE F.DELETE_YN = 'Y' AND F.FOLDER_ID <> F.PARENT_FOLDER_ID AND F.TRASH_ID IN
#{trashId}
AND F.USER_CODE = #{userCode}
AND NOT EXISTS ( SELECT 1 FROM NAS_FILE C WHERE C.FOLDER_ID = F.FOLDER_ID ) AND NOT EXISTS ( SELECT 1 FROM NAS_FOLDER C WHERE C.PARENT_FOLDER_ID = F.FOLDER_ID AND C.FOLDER_ID <> C.PARENT_FOLDER_ID )

